   608	bool SGIImage::writeImage(const QImage &image)
   609	{
   610	//     qDebug() << "writing "; // TODO add filename
   611	    QImage img = image;
   612	    if (img.allGray()) {
   613	        _dim = 2, _zsize = 1;
   614	    } else {
   615	        _dim = 3, _zsize = 3;
   616	    }
   617	
   618	    if (img.format() == QImage::Format_ARGB32) {
   619	        _dim = 3, _zsize++;
   620	    }
   621	
   622	    img = img.convertToFormat(QImage::Format_RGB32);
   623	    if (img.isNull()) {
   624	//         qDebug() << "can't convert image to depth 32";
   625	        return false;
   626	    }
   627	
   628	    _bpc = 1;
   629	    _xsize = img.width();
   630	    _ysize = img.height();
   631	    _pixmin = ~0u;
   632	    _pixmax = 0;
   633	    _colormap = NORMAL;
   634	    _numrows = _ysize * _zsize;
   635	    _starttab = new quint32[_numrows];
   636	    _rlemap.setBaseOffset(512 + _numrows * 2 * sizeof(quint32));
   637	
   638	    if (!scanData(img)) {
   639	//         qDebug() << "this can't happen";
   640	        return false;
   641	    }
   642	
   643	    _rlevector = _rlemap.vector();
   644	
   645	    long verbatim_size = _numrows * _xsize;
   646	    long rle_size = _numrows * 2 * sizeof(quint32);
   647	    for (int i = 0; i < _rlevector.size(); i++) {
   648	        rle_size += _rlevector[i]->size();
   649	    }
   650	
   651	//     qDebug() << "minimum intensity: " << _pixmin;
   652	//     qDebug() << "maximum intensity: " << _pixmax;
